// --- Utilidades comunes de EventPass ------------------------------------
const ahora = () => new Date().toISOString();
const nuevoId = (prefijo) =>
  prefijo + '-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
const norm = (v) => String(v ?? '').trim();
const normEmail = (v) => norm(v).toLowerCase();
// Lee todas las filas de un nodo de Google Sheets ignorando el item vacío que produce "Always Output Data".
const filas = (nodo) => {
  try {
    return $(nodo).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
  } catch (e) {
    return [];
  }
};
const fallo = (status, mensaje, extra = {}) => [{ json: { ok: false, status, body: { ok: false, error: mensaje }, ...extra } }];
const q = $input.first().json.query || {};
const tipo = norm(q.tipo || 'LISTADO').toUpperCase();
const consulta = {
  tipo,
  evento_id: norm(q.evento_id).toUpperCase(),
  categoria: norm(q.categoria),
  grupo_edad: norm(q.grupo_edad),
  visitor_id: norm(q.visitor_id).slice(0, 64) || 'anonimo',
};
if (!['LISTADO', 'DETALLE', 'FILTRO'].includes(tipo)) {
  return fallo(400, 'Tipo de consulta no soportado. Usa LISTADO, DETALLE o FILTRO.', { consulta });
}
if (tipo === 'DETALLE' && !consulta.evento_id) return fallo(400, 'Falta el evento_id.', { consulta });
if (tipo === 'FILTRO' && !consulta.categoria && !consulta.grupo_edad) return fallo(400, 'Indica una categoría o un grupo de edad.', { consulta });
return [{ json: { ok: true, ...consulta } }];

// --- Utilidades comunes de EventPass ------------------------------------
const ahora = () => new Date().toISOString();
const nuevoId = (prefijo) =>
  prefijo + '-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
const norm = (v) => String(v ?? '').trim();
const normEmail = (v) => norm(v).toLowerCase();
// Lee todas las filas de un nodo de Google Sheets ignorando el item vacío que produce "Always Output Data".
const filas = (nodo) => {
  try {
    return $(nodo).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
  } catch (e) {
    return [];
  }
};
const fallo = (status, mensaje, extra = {}) => [{ json: { ok: false, status, body: { ok: false, error: mensaje }, ...extra } }];
// --- Utilidades de eventos e inscripciones ------------------------------
const ZONA_HORARIA = '-05:00'; // Hora de Colombia
function inicioEvento(evento) {
  const [h = '00', m = '00'] = norm(evento.hora).split(':');
  return new Date(`${norm(evento.fecha)}T${h.padStart(2, '0')}:${m.padStart(2, '0')}:00${ZONA_HORARIA}`);
}
const ESTADOS_ACTIVOS = ['CONFIRMADA', 'LISTA_ESPERA'];
function confirmadasDe(inscripciones, eventoId) {
  return inscripciones.filter((i) => i.evento_id === eventoId && ['CONFIRMADA', 'ASISTIO'].includes(i.estado)).length;
}
function listaEsperaDe(inscripciones, eventoId) {
  return inscripciones
    .filter((i) => i.evento_id === eventoId && i.estado === 'LISTA_ESPERA')
    .sort((a, b) => norm(a.fecha_inscripcion).localeCompare(norm(b.fecha_inscripcion)));
}
const fechaLegible = (evento) => {
  const d = inicioEvento(evento);
  if (isNaN(d)) return `${evento.fecha} ${evento.hora}`;
  return d.toLocaleString('es-CO', {
    timeZone: 'America/Bogota', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit',
  });
};
const c = $('Validar consulta').first().json;
const eventos = ($('Agrupar eventos').first().json.eventos || []).filter((e) => e && e.evento_id);
const inscripciones = filas('Leer Inscripciones');
const ahoraMs = Date.now();

const publico = (e) => {
  const capacidad = Number(e.capacidad) || 0;
  const confirmadas = confirmadasDe(inscripciones, e.evento_id);
  const enEspera = listaEsperaDe(inscripciones, e.evento_id).length;
  const cupos = Math.max(0, capacidad - confirmadas);
  const inicio = inicioEvento(e);
  let disponibilidad;
  if (e.estado === 'CANCELADO') disponibilidad = 'CANCELADO';
  else if (e.estado === 'CERRADO') disponibilidad = 'CERRADO';
  else if (inicio.getTime() <= ahoraMs) disponibilidad = 'FINALIZADO';
  else if (cupos > 0) disponibilidad = 'DISPONIBLE';
  else disponibilidad = 'LLENO';
  return {
    evento_id: e.evento_id,
    nombre: e.nombre,
    categoria: e.categoria,
    grupo_edad: e.grupo_edad,
    descripcion: e.descripcion,
    fecha: e.fecha,
    hora: e.hora,
    inicio: isNaN(inicio) ? null : inicio.toISOString(),
    lugar: e.lugar,
    imagen_url: e.imagen_url,
    organizador: e.organizador,
    estado: e.estado,
    motivo_estado: e.motivo_estado || '',
    capacidad,
    inscritos_confirmados: confirmadas,
    lista_espera: enEspera,
    cupos_disponibles: cupos,
    disponibilidad,
    acepta_inscripciones: e.estado === 'PUBLICADO' && inicio.getTime() > ahoraMs,
  };
};

let lista = eventos.map(publico).sort((a, b) => String(a.inicio).localeCompare(String(b.inicio)));
const categorias = [...new Set(lista.map((e) => e.categoria))].sort();
let status = 200;
let body;
if (c.tipo === 'DETALLE') {
  const e = lista.find((x) => x.evento_id === c.evento_id);
  if (e) body = { ok: true, tipo: c.tipo, evento: e };
  else { status = 404; body = { ok: false, error: 'Ese evento no existe o no está publicado.' }; }
  lista = e ? [e] : [];
} else {
  if (c.tipo === 'FILTRO') {
    lista = lista.filter((e) => (!c.categoria || e.categoria === c.categoria) && (!c.grupo_edad || e.grupo_edad === c.grupo_edad));
  }
  body = { ok: true, tipo: c.tipo, total: lista.length, categorias, eventos: lista };
}
return [{ json: { status, body, resultado_count: lista.length } }];

